<svg class="ico" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" xmlns:c2pa="http://c2pa.org/manifest"><metadata><c2pa:manifest></c2pa:manifest></metadata>
@switch($name)
    @case('plus')     <path d="M12 5v14M5 12h14"/> @break
    @case('eye')      <path d="M2 12s3.6-7 10-7 10 7 10 7-3.6 7-10 7S2 12 2 12z"/><circle cx="12" cy="12" r="3"/> @break
    @case('edit')     <path d="M4 20h4L19 9a2.8 2.8 0 0 0-4-4L4 16v4z"/><path d="M13.5 6.5l4 4"/> @break
    @case('trash')    <path d="M4 7h16M9 7V4h6v3M6 7l1 13h10l1-13"/><path d="M10 11v6M14 11v6"/> @break
    @case('download') <path d="M12 4v11M7 10l5 5 5-5M5 20h14"/> @break
    @case('upload')   <path d="M12 20V9M7 14l5-5 5 5M5 4h14"/> @break
    @case('back')     <path d="M15 6l-6 6 6 6"/> @break
    @case('check')    <path d="M5 12.5l4.5 4.5L19 7"/> @break
@endswitch
</svg>
